use num::{BigInt, BigUint, One, ToPrimitive, Zero};

use crate::translation::fixed_point::big_uint_to_ufixed;

/// Convert a `BigUint` to a string interpreted as a floating-point value.
///
/// This function interprets the bits of `uint` according to IEEE 754 floating-point format:
/// - 1 sign bit (MSB)
/// - `exponent_bits` exponent bits (biased representation)
/// - `mantissa_bits` mantissa/significand bits (with implicit leading 1 for normalized numbers)
///
/// # Format
/// The bit layout is: [sign (1 bit)][exponent (E bits)][mantissa (M bits)]
/// where E = num_bits - mantissa_bits - 1
///
/// # Special Values
/// - **Zero**: exponent = 0, mantissa = 0 (returns "0" or "-0")
/// - **Subnormal**: exponent = 0, mantissa ≠ 0 (no implicit leading 1)
/// - **Infinity**: exponent = all 1s, mantissa = 0 (returns "inf" or "-inf")
/// - **NaN**: exponent = all 1s, mantissa ≠ 0 (returns "NaN")
///
/// # Arguments
/// - `uint`: The raw bit pattern to interpret
/// - `num_bits`: Total number of bits in the representation
/// - `mantissa_bits`: Number of bits in the mantissa (must be >= 0 and < num_bits - 1)
///
/// # Returns
/// A string representation of the floating-point value, or an error message if parameters are invalid.
pub(crate) fn big_uint_to_float(uint: &BigUint, num_bits: u64, mantissa_bits: i64) -> String {
    // Validate input parameters
    if num_bits < 2 {
        return "Total bits must be at least 2".to_string();
    }
    if mantissa_bits < 0 {
        return "Mantissa bits must be non-negative".to_string();
    }
    if mantissa_bits as u64 >= num_bits {
        return "Mantissa bits must be less than total bits".to_string();
    }

    let exponent_bits = num_bits - mantissa_bits as u64 - 1;
    if exponent_bits >= 64u64 {
        return "Exponent bits too large, must be at most 63".to_string();
    }

    // Extract components using bit operations
    let sign_bit = uint.bit(num_bits - 1);
    let mantissa_factor = BigUint::one() << mantissa_bits;
    let mantissa_mask = &mantissa_factor - BigUint::one();
    let raw_mantissa: BigUint = uint & &mantissa_mask;
    let max_exponent = (BigUint::one() << exponent_bits) - BigUint::one();
    let raw_exponent: BigUint = (uint >> mantissa_bits) & &max_exponent;
    let subnormal = raw_exponent.is_zero();
    let zero_mantissa = raw_mantissa.is_zero();

    // Check zero_mantissa first as it's typically cheaper
    if zero_mantissa {
        if subnormal {
            // Zero (positive or negative)
            return if sign_bit {
                "-0".to_string()
            } else {
                "0".to_string()
            };
        }
        if raw_exponent == max_exponent {
            // Infinity
            return if sign_bit {
                "-inf".to_string()
            } else {
                "inf".to_string()
            };
        }
    } else if raw_exponent == max_exponent {
        // NaN (exponent all 1s with non-zero mantissa)
        return "NaN".to_string();
    }
    let bias = (BigInt::one() << (exponent_bits - 1)) - BigInt::one();
    let exponent_value = BigInt::from(raw_exponent) - bias;
    let mantissa_value = if subnormal {
        // Denormalized number: no implicit leading 1
        raw_mantissa.clone()
    } else {
        // Normalized number: add implicit leading 1
        &raw_mantissa + &mantissa_factor
    };
    if let Some(exponent_i64) = exponent_value.to_i64() {
        let lg_scale_factor = mantissa_bits - exponent_i64;
        let unsigned_str = big_uint_to_ufixed(&mantissa_value, lg_scale_factor);
        if sign_bit {
            format!("-{}", unsigned_str)
        } else {
            unsigned_str
        }
    } else {
        // Exponent too large to represent
        "Exponent too large to represent".to_string()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_positive_zero() {
        // 32-bit IEEE 754: sign=0, exponent=0, mantissa=0
        let zero = BigUint::from(0u32);
        let result = big_uint_to_float(&zero, 32, 23);
        assert_eq!(result, "0");
    }

    #[test]
    fn test_negative_zero() {
        // 32-bit IEEE 754: sign=1, exponent=0, mantissa=0 -> -0
        let neg_zero = BigUint::from(0x80000000u32);
        let result = big_uint_to_float(&neg_zero, 32, 23);
        assert_eq!(result, "-0");
    }

    #[test]
    fn test_positive_infinity() {
        // 32-bit IEEE 754: sign=0, exponent=all 1s, mantissa=0
        let pos_inf = BigUint::from(0x7f800000u32);
        let result = big_uint_to_float(&pos_inf, 32, 23);
        assert_eq!(result, "inf");
    }

    #[test]
    fn test_negative_infinity() {
        // 32-bit IEEE 754: sign=1, exponent=all 1s, mantissa=0
        let neg_inf = BigUint::from(0xff800000u32);
        let result = big_uint_to_float(&neg_inf, 32, 23);
        assert_eq!(result, "-inf");
    }

    #[test]
    fn test_nan() {
        // 32-bit IEEE 754: sign=0, exponent=all 1s, mantissa=non-zero
        let nan = BigUint::from(0x7f800001u32);
        let result = big_uint_to_float(&nan, 32, 23);
        assert_eq!(result, "NaN");
    }

    #[test]
    fn test_nan_negative() {
        // 32-bit IEEE 754: sign=1, exponent=all 1s, mantissa=non-zero
        let nan = BigUint::from(0xff800001u32);
        let result = big_uint_to_float(&nan, 32, 23);
        assert_eq!(result, "NaN");
    }

    #[test]
    fn test_subnormal_positive() {
        // 32-bit IEEE 754: sign=0, exponent=0, mantissa=non-zero (subnormal/denormalized)
        let subnormal = BigUint::from(0x00000001u32);
        let result = big_uint_to_float(&subnormal, 32, 23);
        // Subnormal numbers have implicit leading 0, not 1
        assert_eq!(
            result,
            "0.000000000000000000000000000000000000000000000700649232162408535461864791644958065640130970938257885878534141944895541342930300743319094181060791015625"
        );
    }

    #[test]
    fn test_subnormal_negative() {
        // 32-bit IEEE 754: sign=1, exponent=0, mantissa=non-zero (negative subnormal)
        let subnormal = BigUint::from(0x80000001u32);
        let result = big_uint_to_float(&subnormal, 32, 23);
        assert_eq!(
            result,
            "-0.000000000000000000000000000000000000000000000700649232162408535461864791644958065640130970938257885878534141944895541342930300743319094181060791015625"
        );
    }

    #[test]
    fn test_max_subnormal() {
        // 32-bit IEEE 754: sign=0, exponent=0, mantissa=all 1s (max subnormal)
        let max_subnormal = BigUint::from(0x007fffffu32);
        let result = big_uint_to_float(&max_subnormal, 32, 23);
        assert_eq!(
            result,
            "0.000000000000000000000000000000000000005877471053462205377435147224246436744135262143729466669285872652857944352378094521327511756680905818939208984375"
        );
    }

    #[test]
    fn test_64bit_with_uncommon_mantissa() {
        // 64-bit but with 40-bit mantissa instead of standard 52
        let val = BigUint::from(0x3ff0000000000000u64);
        let result = big_uint_to_float(&val, 64, 40);
        assert_eq!(
            result,
            "0."
        );
    }

    #[test]
    fn test_non_standard_16bit_format() {
        // 16-bit with only 5-bit mantissa (non-standard)
        // This leaves 10 bits for exponent, which is unusually large
        let val = BigUint::from(0x7c00u16); // normalized 1.0-like
        let result = big_uint_to_float(&val, 16, 5);
        assert_eq!(
            result,
            "6243497100631984462763194459586332611497196285329942301718313919250743477639531240240612206126983942319653862242813245790895951358576570612580352"
        );
    }

    #[test]
    fn test_non_standard_24bit_wide_exponent() {
        // 24-bit with 2-bit mantissa (very wide exponent: 21 bits)
        let val = BigUint::from(0x400000u32); // Just over midpoint
        let result = big_uint_to_float(&val, 24, 2);
        assert_eq!(result, "2");
    }

    #[test]
    fn test_128bit_infinity() {
        // 128-bit infinity
        let mut bytes = [0u8; 16];
        bytes[0] = 0x7f;
        bytes[1] = 0x80;
        let val = BigUint::from_bytes_be(&bytes);
        let result = big_uint_to_float(&val, 128, 119);
        assert_eq!(result, "inf");
    }

    #[test]
    fn test_exponent_bits_too_large_error() {
        // 64 exponent bits with 0 mantissa bits - should error
        let val = BigUint::from(0xffffffffffffffffu64);
        let result = big_uint_to_float(&val, 80, 0);
        assert_eq!(result, "Exponent bits too large, must be at most 63");
    }

    #[test]
    fn test_8bit_nan() {
        // 8-bit with 3-bit mantissa (4-bit exponent)
        let val = BigUint::from(0x7fu8); // All 1s
        let result = big_uint_to_float(&val, 8, 3);
        assert_eq!(result, "NaN");
    }

    #[test]
    fn test_8bit_subnormal_infinity_nan() {
        // 8-bit: test all special cases with minimal bits
        // Positive infinity
        let pos_inf_8 = BigUint::from(0x78u8); // exponent all 1s, mantissa 0
        let result = big_uint_to_float(&pos_inf_8, 8, 3);
        assert_eq!(result, "inf");

        // NaN
        let nan_8 = BigUint::from(0x79u8); // exponent all 1s, mantissa non-zero
        let result = big_uint_to_float(&nan_8, 8, 3);
        assert_eq!(result, "NaN");

        // Subnormal
        let subnorm_8 = BigUint::from(0x01u8); // exponent 0, mantissa non-zero
        let result = big_uint_to_float(&subnorm_8, 8, 3);
        assert_eq!(result, "0.0009765625");
    }

    #[test]
    fn test_96bit_non_standard() {
        // 96-bit (not a power of 2) with 48-bit mantissa
        let bytes = [0x7fu8; 12];
        let val = BigUint::from_bytes_be(&bytes);
        let result = big_uint_to_float(&val, 96, 80);
        assert_eq!(
            result,
            ""
        );
    }
}
